			return capabilities.replaySafe() && capabilities.correlationReads() >= 0L
					&& (capabilities.correlationReads() & keys & ~(available | SlotPlan.assuredMask(filter.arg))) == 0L
					&& sweepSafe(filter.arg, keys, available);
